  for (const s of [-1, 1]) {
    const cIdx = P.length / 3;
    P.push(cx + s * halfWidth, cy, cz);
    N.push(s, 0, 0);
    PT.push(part);
    const ring = P.length / 3;
    for (let i = 0; i <= segs; i++) {
      const a = (i / segs) * TAU;
