    [[-tx, 1, tz], [tx, 1, tz], [tx, 1, -tz], [-tx, 1, -tz]],
    [[-bx, -1, -bz], [bx, -1, -bz], [bx, -1, bz], [-bx, -1, bz]],
  ];
