    }
    gl.depthMask(true);
    gl.disable(gl.BLEND);
  }

  _addLampGlows(cars, glows, time) {
    for (const car of cars) {
      const fwd = car.forward();
      const right = [fwd[2], 0, -fwd[0]];
      for (const sx of [-0.62, 0.62]) {
